def max_sub_array_sum(nums, size):
    if len(nums) < size:
        return None

    current_sum = max_sum = nums[0]

    for i in range(1, size):
        current_sum += nums[i]
        if current_sum > max_sum:
            max_sum = current_sum

        if current_sum < 0:
            current_sum = 0

    return max_sum
