def is_magic_square(matrix):
    if len(set([len(row) for row in matrix])) != 1:
        return False

    rows_sum = sum(matrix[0])
    cols_sum = sum(matrix[i][i] for i in range(len(matrix)))

    for r in range(len(matrix)):
        if sum(matrix[r]) != rows_sum or sum(matrix[i][r] for i in range(len(matrix))) != cols_sum:
            return False

    diagonals_sum = sum(matrix[i][i] for i in range(len(matrix)))
    reverse_diagonals_sum = sum(matrix[i][len(matrix)-1-i] for i in range(len(matrix)))

    return diagonals_sum == cols_sum == reverse_diagonals_sum == rows_sum
```

