def max_sum_increasing_subseq(arr, n, k):
    dp = [arr[0]] * (n + 1)

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    return dp[k]
