def large_product(list1, list2, n):
    max_products = []
    for i in range(len(list1)):
        for j in range(len(list2)):
            product = list1[i] * list2[j]
            if len(max_products) < n:
                max_products.append(product)
            else:
                if product > max_products[-1]:
                    max_products.pop()
                    max_products.append(product)
    return max_products
