        result.append(s[q_start+1:q_end])
        start = q_end + 1
    return result

def get_ludic(n):
    if n < 8:
        return []
    ludics = [1, 2, 3, 5, 7]
    i = 4
    while True:
        next_ludic = ludics[-1] + i
        if next_ludic > n:
            break
        ludics.append(next_ludic)
        j = 1
        while (j * ludics[-1]) <= n:
            ludics.append(ludics[-1] - j)
            j += 1
        i += 1
    return ludics[:-1]

