```python
def magic_square_test(matrix):
    n = len(matrix)
    if n != len(matrix[0]):
        return False

    # Calculate the sum of the first row
    target_sum = sum(matrix[0])

    # Check each row
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check each column
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target_sum:
            return False

    # Check both diagonals
    if sum(matrix[i][i] for i in range(n)) != target_sum or sum(matrix[i][n-i-1] for i in range(n)) != target_sum:
        return False

    return True
```

```python
def max_sum_increasing_subseq(arr, n, k, m):
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if arr[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - arr[i - 1]] + arr[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][k]
```

