def check_min_heap(arr):
    n = len(arr)
    for i in range(n // 2 - 1, -1, -1):
        if arr[i] > max(arr[2 * i + 1], arr[2 * i + 2]):
            return False
    return True
```

```python
def prime_num(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
```

